    {
      "stem": "妈妈买了23个苹果，准备平均分给5个小朋友。每个小朋友能分到几个苹果？还剩几个苹果？",
      "answer": "4个……3个",
      "solution": "用总数23除以人数5，即23÷5=4（个）……3（个）。商表示每人分到的数量，余数表示剩下的数量。"
    },
    {
      "stem": "二（1）班有38名同学去划船，每条船最多坐6人。他们至少需要租几条船？",
      "answer": "7条",
      "solution": "38÷6=6（条）……2（人）。剩下的2人也需要一条船，所以需要用“进一法”，6+1=7条。"
    },
    {
      "stem": "做一件衬衫需要钉5颗纽扣，现在有42颗纽扣，最多可以做几件这样的衬衫？",
      "answer": "8件",
      "solution": "42÷5=8（件）……2（颗）。剩下的2颗不够做一件衬衫，所以需要用“去尾法”，最多只能做8件。"
    },
    {
      "stem": "超市里促销，每盒饼干8元。小明带了50元钱，最多可以买几盒饼干？",
      "answer": "6盒",
      "solution": "50÷8=6（盒）……2（元）。剩下的2元不够买一盒，所以最多买6盒。"
    },
    {
      "stem": "老师要把45本故事书平均分给7个小组，每个小组分到几本？还剩下几本？",
      "answer": "6本……3本",
      "solution": "45÷7=6（本）……3（本）。根据乘法口诀六七四十二，45减42余3，所以每组6本，剩3本。"
    }
  ]
}
